message.content:
[
  {
    "pd_harm_distress": "hands probably shaking",
    "sys_consequence_reasoning": "Nobody gets hurt if I act, and five might die if I don't",
    "sys_rule_justification": "bound to help when all it costs you is nerve",
    "pda_responsibility": "tell them exactly what I did and why",
    "pda_repair_intention": "offer to cover any damage to the barrier"
  },
  {
    "sys_rule_justification": "You don't get to watch people die if saving them is within reach",
    "sys_consequence_reasoning": "The train ends up against a barrier and the workers go home",
    "pda_responsibility": "give them my name so any repair bill or report comes to me",
    "pda_repair_intention": "give them my name so any repair bill or report comes to me"
  },
  {
    "pd_harm_distress": "though my stomach's in knots",
    "sys_rule_justification": "protect life when you safely can",
    "sys_consequence_reasoning": "Five lives against an empty siding isn't close",
    "pd_personal_consequence_anxiety": "What worries me is messing up something I don't understand",
    "pda_repair_intention": "report it straight away to the signal staff so they can check"
  },
  {
    "sys_rule_justification": "I don't think anyone's allowed to just stand there",
    "sys_consequence_reasoning": "Those five keep their lives",
    "pda_repair_intention": "ring the rail company, explain, and pay for the fix if they ask"
  },
  {
    "ce_mental_state_attribution": "those five not even seeing it coming",
    "sys_rule_justification": "if you can keep someone from harm without harming anyone else, you must",
    "sys_consequence_reasoning": "benefit is five people alive, and the downside... is a train stopped",
    "pda_repair_intention": "write down what happened while it's fresh and hand it to the station manager"
  },
  {
    "pd_personal_consequence_anxiety": "scared of getting it wrong or getting in trouble",
    "sys_consequence_reasoning": "Five workers could be killed, the siding is empty",
    "sys_rule_justification": "saving a life outranks a 'staff only' sign",
    "pda_responsibility": "If anything gets damaged, that's on me",
    "pda_repair_intention": "own up, and offer to pay or help sort it"
  },
  {
    "pd_harm_distress": "seconds that scare me",
    "sys_consequence_reasoning": "train into the siding, barrier stops it, and the five on the main line walk away",
    "sys_rule_justification": "doing nothing when rescue is safe and simple is a failure of duty",
    "pda_repair_intention": "flag it to maintenance and stick around to tell them"
  },
  {
    "pd_harm_distress": "heart hammering the whole time",
    "ce_contextual_explanation": "Those workers have families waiting",
    "sys_rule_justification": "Keeping people from dying when you're able is about as basic a moral rule",
    "pda_repair_intention": "make sure the railway knows too, so the switch gets put back"
  },
  {
    "ce_mentalizing_difficulty": "Maybe the workers have a way off the track I can't see",
    "sys_consequence_reasoning": "Five lives at stake, zero people in the siding",
    "sys_rule_justification": "each of us is responsible for not letting preventable deaths happen",
    "pda_repair_intention": "apologise for interfering, and offer to explain it on any incident report"
  },
  {
    "sys_rule_justification": "There's a line I won't cross: I won't let people be killed",
    "sys_consequence_reasoning": "Pulling means five workers survive and... nobody's hurt",
    "pd_personal_consequence_anxiety": "What still nags at me is the aftermath",
    "pda_repair_intention": "explain why I did it, and offer to fill in whatever report"
  }
]
